local UIBattlingPickCardSkillCard = Class('UIBattlingPickCardSkillCard')

------------ LifeCycle ------------

function UIBattlingPickCardSkillCard:__init()
    self:CleanField()
end

function UIBattlingPickCardSkillCard:__delete()
    self:CleanField()
end

function UIBattlingPickCardSkillCard:CleanField()
    self.tagCells = nil
    self.callBack = nil
    self.indexInConfig = nil
    self.posData = nil
end

function UIBattlingPickCardSkillCard:Awake()
    self.tagCells = {}
    self.indexInConfig = 0
    self.posData = {}
end

function UIBattlingPickCardSkillCard:Start()
    UIEventProxy.Create(self.Btn_Click.gameObject).onPointerClick = Bind(self, self.ActionOnClick)
end

function UIBattlingPickCardSkillCard:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

------------ LifeCycle ------------

function UIBattlingPickCardSkillCard:ActionOnClick()
    local skillClickType = self.skillCardData.clickType --技能点选规则（1、友方；2、敌方；3、全体；4、自身）
    local isEveryone = self.skillCardData.isEveryone --是否无需点选（0、需点选；1、不需点选）
    if skillClickType == 1 and (not isEveryone) then
        local battleDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
        if battleDialog then
            battleDialog:OnBuffSkillCardClick(nil, { pos = self.posData, targetId = nil }, { skillIndex = self.indexInConfig })
        end
    else --其他技能
        local skillCardPosData = self.posData
        local data2Logic = { pos = skillCardPosData, params = { skillIndex = self.indexInConfig } }
        xTry(function()
            local battlingDialog = UIBattlingCtrlMgr:GetInstance().tableBattlingDialog
            if battlingDialog and (not isNull(battlingDialog.curAttTargetId)) then
                data2Logic.targetId = checkNumber(battlingDialog.curAttTargetId)
            end
        end)
        Events.Broadcast(Constants.EventNames.BattleInputUse, data2Logic)
    end
    if self.callBack then
        self.callBack()
    end
end


function UIBattlingPickCardSkillCard:InitTagCell()
    if isNull(self.tagCells) then self.tagCells = {} end
    local go = KTool.Instantiate(self.SkillTagList.gameObject, self.SkillTagCell.gameObject)
    KTool.SetActive(go, true)
    table.insert(self.tagCells, go)
    return go
end

function UIBattlingPickCardSkillCard:CleanTagCells()
    if isNull(self.tagCells) then return end
    for i = #self.tagCells, 1, -1 do
        KTool.SafeDelete(self.tagCells[i].gameObject)
    end
    self.tagCells = nil
end

function UIBattlingPickCardSkillCard:SetTagCellInfo(go, desc)
    local txtDesc = go.transform:Find("Text_SkillTag").gameObject:GetComponent(typeof(CS.UnityEngine.UI.Text))
    txtDesc.text = desc
end

function UIBattlingPickCardSkillCard:SetSkillTag(abstractLabel, star)
    self:CleanTagCells()
    ---@type CardProgressionSkillUtils
    local CardProgressionSkillUtils     = import("Game.CardProgression.CardProgressionSkillUtils")
    local skillTags = CardProgressionSkillUtils.GetSkillTags(abstractLabel, star)
    KTool.SetActive(self.SkillTagList.gameObject, skillTags and #skillTags > 0)
    local limitValueShow = 4
    for i, labelId in ipairs(skillTags) do
        if i <= limitValueShow then
            local descTag = CfUtils.GetCfData(AutoIds.IdSetting284, labelId, "desc", Constants.DataType.LocalString)
            local goCell = self:InitTagCell()
            self:SetTagCellInfo(goCell, descTag)
        end
    end
end

function UIBattlingPickCardSkillCard:SetSkillCardInfo(skillCardId, star, posData, index)
    xTry(function()
        -- print("->UIBattlingPickCardSkillCard:SetSkillCardInfo", skillCardId, star, posData, index)
        self.skillCardData = UIBattlingTools.GetSkillCardInfoByTwoParam(skillCardId)
        self.indexInConfig = checkInt(index)
        self.posData = posData
        local skillType = self.skillCardData.skillType -- index(A/B)
        local skillLabel = self.skillCardData.label -- 类型图标
        local abstractLabel = self.skillCardData.abstractLabel --Tags
        local skillName =  self.skillCardData.skillName
        local isAoe =  checkBool(checkNumber(self.skillCardData.isAoe) > 0)
        local roleId, skillIndex = UIBattlingDataMgr:GetSkillCardRoleIdWithIndexId(skillCardId)
        local roleView = BattleViewMgr:FindRoleView(roleId)
        local cardId = roleView.typeId
        local cardVo = CardConfMgr:GetCardByRefId(cardId)
        local rare = cardVo.rare
        local strSkillDesc = UIBattlingTools.GetSkillDescInBattle(skillCardId, star, rare, true)
        local damageDesc = UIBattlingTools.GetSkillDamageTypeDescInBattle(skillCardId, star)
        local skillDesc = string.len(damageDesc) > 0 and strSkillDesc .. "\n" .. damageDesc or strSkillDesc
        self.ImgSkillIndexBg.Status = skillType > 1 and 2 or 1
        self.ImgSkillIndexBg:Reset()
        self.ImgSkillIndex.Status = skillType > 1 and 2 or 1
        self.ImgSkillIndex:Reset()
        -- self.TxtDesc.text = checkString(skillDesc)
        CfUtils.FillText(self.TxtDesc, checkString(skillDesc))
        local condition = skillLabel >= 1 and skillLabel <= 4 and isAoe
        local iconPath = condition and UIBattlingTools.GetEnemySkillTypeAOEIconPath(skillLabel)
                or UIBattlingTools.GetEnemySkillTypeIconPath(skillLabel)
        self.SkillTypeIcon:LoadSprite(iconPath)
        self.TxtName.text = checkString(skillName)
        self:SetSkillTag(abstractLabel, star)
        self:SetSkillCard(skillCardId, star)
    end)
end

function UIBattlingPickCardSkillCard:SetCallBack(cb)
    self.callBack = cb
end

function UIBattlingPickCardSkillCard:SetSkillCard(skillCardId, star)
    local roleId, skillIndex = UIBattlingDataMgr:GetSkillCardRoleIdWithIndexId(skillCardId)
    local skillData = { skillId = skillCardId, star = star, skillLv = 1, skillIndex = self.indexInConfig, roleId = roleId }
    local skillCardNodeLB = GetLuaBehaviour(UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.PATH_SKILLCARD_GO, self.Root_SkillCard), Constants.UIBattlingLuaTablePath.SkillCardsNodePath)
    local skillCard = skillCardNodeLB.Env
    skillCard:SetSkillCardInfo(skillData)
    skillCard:RemoveListener()
    skillCard:SetSkillCardCG2Show()
    skillCard:SetEventReceiverEnableState(false)
    if UIBattlingCtrlMgr:GetInstance():CheckSkillCardLockStatus(skillCard) then
        skillCard:SkillCardLocked()
    end
end

return UIBattlingPickCardSkillCard